import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

type MessageValidator = (message: Record<string, unknown>) => ValidationResult;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = messageValidators[message.type];
  return validator ? validator(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (hasInvalidSessionLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const limit = message.limit === undefined ? {} : {limit: message.limit as number};

  if (message.before === undefined) return {valid: true, data: {type: 'list_sessions', ...limit}};
  const before = validateSessionCursor(message.before);
  if (!before.valid) return before;
  return {valid: true, data: {type: 'list_sessions', ...limit, before: before.cursor}};
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  if (hasInvalidConversationLimit(message.limit)) {
    return {valid: false, error: 'list_conversations limit must be an integer between 1 and 200'};
  }
  if (message.before === undefined) return {valid: true, data: conversationMessage(message)};
  if (!isRecord(message.before)) return {valid: false, error: 'list_conversations before must be an object'};
  const before = message.before;
  if (typeof before.updatedAt !== 'string' || Number.isNaN(Date.parse(before.updatedAt))) {
    return {valid: false, error: 'list_conversations before.updatedAt must be a valid date'};
  }
  if (!isValidConversationSessionId(before.sessionId)) {
    return {valid: false, error: 'list_conversations before.sessionId must be 1-128 characters'};
  }
  return {
    valid: true,
    data: {
      ...conversationMessage(message),
      before: {updatedAt: before.updatedAt, sessionId: before.sessionId},
    },
  };
}

function conversationMessage(message: Record<string, unknown>): {type: 'list_conversations'; limit?: number} {
  return message.limit === undefined
    ? {type: 'list_conversations'}
    : {type: 'list_conversations', limit: message.limit as number};
}

function hasInvalidSessionLimit(limit: unknown): boolean {
  return limit !== undefined && (!Number.isInteger(limit) || (limit as number) < 0);
}

function hasInvalidConversationLimit(limit: unknown): boolean {
  if (limit === undefined) return false;
  if (!Number.isInteger(limit) || (limit as number) < 1) return true;
  return (limit as number) > 200;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function validateSessionCursor(
  value: unknown
): {valid: true; cursor: {updatedAt: string | number; sessionId: string}} | {valid: false; error: string} {
  if (!isRecord(value)) return {valid: false, error: 'list_sessions before must be an object'};
  if (typeof value.sessionId !== 'string' || value.sessionId.length < 1 || value.sessionId.length > 128) {
    return {valid: false, error: 'list_sessions before.sessionId must be 1-128 characters'};
  }
  if (!isValidSessionDate(value.updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid date'};
  }
  return {valid: true, cursor: {updatedAt: value.updatedAt, sessionId: value.sessionId}};
}

function isValidSessionDate(value: unknown): value is string | number {
  if (typeof value === 'string') return !Number.isNaN(Date.parse(value));
  return typeof value === 'number' && Number.isFinite(value) && !Number.isNaN(new Date(value).getTime());
}

function isValidConversationSessionId(value: unknown): value is string {
  return typeof value === 'string' && value.length >= 1 && value.length <= 128;
}

const messageValidators: Record<string, MessageValidator> = {
  ['user_message']: validateUserMessage,
  ping: validatePingMessage,
  ['list_sessions']: validateListSessionsMessage,
  ['list_conversations']: validateListConversationsMessage,
};
